fn remove_duplicates(mut v: Vec<u64>) -> Vec<u64> {
    let mut seen = std::collections::HashSet::new();
    let mut out = Vec::new();
    while let Some(x) = v.pop() {
        if !seen.contains(&x) {
            seen.insert(x);
            out.push(x);
        }
    }
    out.reverse();
    out
}

